using System;

using UnityEngine;

namespace IronRing.Presentation.HubPhase
{
    /// <summary>
    /// Story 014 prefab catalog: the interior NPC walker piece and one piece per facility id.
    /// Generated by IronRing.Presentation.HubPhase.Editor.HubPhasePrefabBuild.Generate (prefabs under Assets/Prefabs/HubPhase/).
    /// </summary>
    [CreateAssetMenu(menuName = "IronRing/Hub Phase Prefab Catalog")]
    public sealed class HubPhasePrefabCatalog : ScriptableObject
    {
        [Serializable]
        private sealed class FacilityEntry
        {
            [SerializeField] private string _facilityId;
            [SerializeField] private GameObject _prefab;
            public string FacilityId => _facilityId;
            public GameObject Prefab => _prefab;
        }

        [Header("Interior pieces")]
        [SerializeField] private GameObject _npc;
        [SerializeField] private FacilityEntry[] _facilities = Array.Empty<FacilityEntry>();

        /// <summary>NPC walker prefab (SpriteRenderer at the root).</summary>
        public GameObject Npc => _npc;

        /// <summary>Facility prefab for facilityId, or null when the catalog has none.</summary>
        public GameObject Facility(string facilityId)
        {
            foreach (FacilityEntry entry in _facilities) if (entry != null && entry.FacilityId == facilityId) return entry.Prefab;
            return null;
        }

        /// <summary>Loads Resources/HubPhase/HubPhasePrefabCatalog, logging an error when it is missing.</summary>
        public static HubPhasePrefabCatalog Load()
        {
            var catalog = UnityEngine.Resources.Load<HubPhasePrefabCatalog>("HubPhase/HubPhasePrefabCatalog");
            if (catalog == null) UnityEngine.Debug.LogError("HubPhase: Resources/HubPhase/HubPhasePrefabCatalog.asset이 없습니다. HubPhasePrefabBuild.Generate를 실행하세요.");
            return catalog;
        }
    }
}
